import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [symbol, setSymbol] = useState('AAPL');
  const [stockData, setStockData] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchStock = async () => {
    setLoading(true);
    try {
        const res = await axios.get("http://localhost:5000/stock", {
            params: { symbol }
        });
    setStockData(res.data.data);
  } catch (err) {
    alert('Failed to fetch data');
  }
  setLoading(false);
};

useEffect(() => {
  fetchStock();
}, []);

return (
    <div style={{ padding: '2rem' }}>
      <h1>Stock Data Viewer</h1>
      <input
          type="text"
          value={symbol}
          onChange={(e) => setSymbol(e.target.value)}
      />
      <button onClick={fetchStock}>Fetch Data</button>

      {loading ? (
          <p>Loading...</p>
      ) : (
          <table border="1" cellPadding="5" style={{ marginTop: '1rem' }}>
            <thead>
            <tr>
              <th>Datetime</th>
              <th>Open</th>
              <th>High</th>
              <th>Low</th>
              <th>Close</th>
              <th>Volume</th>
            </tr>
            </thead>
            <tbody>
            {stockData.map((row, i) => (
                <tr key={i}>
                  <td>{row.Datetime}</td>
                  <td>{row.Open}</td>
                  <td>{row.High}</td>
                  <td>{row.Low}</td>
                  <td>{row.Close}</td>
                  <td>{row.Volume}</td>
                </tr>
            ))}
            </tbody>
          </table>
      )}
    </div>
);
}

export default App;
